import React, { useEffect, useMemo, useRef, useState } from 'react';
import './App.css';

type CounterButton = { id: number; count: number };
type NavigationKey = 'ArrowUp' | 'ArrowDown' | 'Home' | 'End';

const MIN_LIMIT = 1;
const MAX_LIMIT = 10;
const DEFAULT_LIMIT = 5;
const NAVIGATION_KEYS: NavigationKey[] = ['ArrowUp', 'ArrowDown', 'Home', 'End'];

function clampLimit(raw: string): number {
  const parsed = Number(raw);
  if (!Number.isFinite(parsed)) return MIN_LIMIT;
  return Math.min(MAX_LIMIT, Math.max(MIN_LIMIT, Math.trunc(parsed)));
}

export default function App() {
  const [counters, setCounters] = useState<CounterButton[]>([{ id: 1, count: 0 }]);
  const [limit, setLimit] = useState(DEFAULT_LIMIT);
  const [focusId, setFocusId] = useState(1);
  const nextId = useRef(2);
  const counterRefs = useRef(new Map<number, HTMLButtonElement>());
  const pendingFocusId = useRef<number | null>(null);

  useEffect(() => {
    const pendingId = pendingFocusId.current;
    if (pendingId === null) return;
    pendingFocusId.current = null;
    counterRefs.current.get(pendingId)?.focus();
  }, [counters]);

  const combinedValue = useMemo(
    () => counters.reduce((sum, counter) => sum + counter.count, 0),
    [counters]
  );

  const isInitial = limit === DEFAULT_LIMIT
    && counters.length === 1
    && counters[0].id === 1
    && counters[0].count === 0;

  const statusText = 'Counters: ' + counters.length + ' of ' + limit
    + '. Combined value: ' + combinedValue + '.';

  const counterRowId = (id: number): string => 'counter-row-' + id;
  const counterButtonId = (id: number): string => 'counter-button-' + id;
  const removeButtonId = (id: number): string => 'remove-counter-' + id;
  const counterLabel = (counter: CounterButton): string => (
    'Counter ' + counter.id + ', value ' + counter.count
  );
  const removeCounterLabel = (id: number): string => 'Remove counter ' + id;

  const setCounterRef = (id: number, element: HTMLButtonElement | null) => {
    if (element) counterRefs.current.set(id, element);
    else counterRefs.current.delete(id);
  };

  const onCounterFocus = (id: number) => {
    setFocusId(id);
  };

  const onClick = (id: number) => {
    setFocusId(id);
    setCounters((current) => {
      const updated = current.map((counter) => (
        counter.id === id ? { ...counter, count: counter.count + 1 } : counter
      ));

      if (current.length >= limit) return updated;
      const created = { id: nextId.current, count: 0 };
      nextId.current += 1;
      return [...updated, created];
    });
  };

  const removeCounter = (id: number) => {
    if (counters.length === 1) return;
    const removedIndex = counters.findIndex((counter) => counter.id === id);
    if (removedIndex < 0) return;

    const survivors = counters.filter((counter) => counter.id !== id);
    const targetIndex = Math.min(removedIndex, survivors.length - 1);
    const targetId = survivors[targetIndex].id;

    pendingFocusId.current = targetId;
    setFocusId(targetId);
    setCounters(survivors);
  };

  const onLimitInput = (raw: string) => {
    const nextLimit = clampLimit(raw);
    const normalized = counters.slice(0, nextLimit);
    const normalizedFocusId = normalized.some((counter) => counter.id === focusId)
      ? focusId
      : normalized[normalized.length - 1].id;

    setLimit(nextLimit);
    setCounters(normalized);
    setFocusId(normalizedFocusId);
  };

  const resetCounters = () => {
    pendingFocusId.current = null;
    nextId.current = 2;
    setLimit(DEFAULT_LIMIT);
    setCounters([{ id: 1, count: 0 }]);
    setFocusId(1);
  };

  const focusCounter = (id: number) => {
    setFocusId(id);
    counterRefs.current.get(id)?.focus();
  };

  const onCounterKeyDown = (event: React.KeyboardEvent<HTMLButtonElement>, id: number) => {
    const key = event.key as NavigationKey;
    if (!NAVIGATION_KEYS.includes(key)) return;

    event.preventDefault();
    const currentIndex = counters.findIndex((counter) => counter.id === id);
    if (currentIndex < 0) return;

    let targetIndex = currentIndex;
    if (key === 'ArrowUp') targetIndex = (currentIndex + counters.length - 1) % counters.length;
    else if (key === 'ArrowDown') targetIndex = (currentIndex + 1) % counters.length;
    else if (key === 'Home') targetIndex = 0;
    else if (key === 'End') targetIndex = counters.length - 1;

    focusCounter(counters[targetIndex].id);
  };

  return (
    <main className='page'>
      <section className='card'>
        <h1>Dynamic Counter Buttons</h1>
        <p className='subtitle'>
          Grow independent counters, remove them by stable identity, and keep keyboard focus predictable.
        </p>

        <div className='toolbar'>
          <label className='limit-control' htmlFor='counter-limit'>
            Counter limit
            <input
              id='counter-limit'
              type='number'
              min={MIN_LIMIT}
              max={MAX_LIMIT}
              value={limit}
              onChange={(event) => onLimitInput(event.target.value)}
            />
          </label>
          <button
            id='reset-counters'
            className='reset-button'
            type='button'
            disabled={isInitial}
            onClick={resetCounters}
          >
            Reset
          </button>
        </div>

        <p id='counter-status' className='status' role='status' aria-live='polite'>
          {statusText}
        </p>

        <div
          className='counter-list'
          role='list'
          aria-label='Dynamic counter buttons'
          aria-describedby='counter-status'
        >
          {counters.map((counter) => (
            <div
              key={counter.id}
              id={counterRowId(counter.id)}
              className='counter-row'
              role='listitem'
              data-counter-id={counter.id}
            >
              <button
                id={counterButtonId(counter.id)}
                ref={(element) => setCounterRef(counter.id, element)}
                className='counter-button'
                type='button'
                aria-label={counterLabel(counter)}
                tabIndex={focusId === counter.id ? 0 : -1}
                onFocus={() => onCounterFocus(counter.id)}
                onKeyDown={(event) => onCounterKeyDown(event, counter.id)}
                onClick={() => onClick(counter.id)}
              >
                Counter {counter.id}: <span className='counter-value'>{counter.count}</span>
              </button>
              <button
                id={removeButtonId(counter.id)}
                className='remove-button'
                type='button'
                aria-label={removeCounterLabel(counter.id)}
                aria-controls={counterRowId(counter.id)}
                disabled={counters.length === 1}
                onClick={() => removeCounter(counter.id)}
              >
                Remove
              </button>
            </div>
          ))}
        </div>
      </section>
    </main>
  );
}

