:root {
  color-scheme: dark;
}

* {
  box-sizing: border-box;
}

html, body, #root {
  margin: 0;
  min-width: 0;
  min-height: 100%;
  background: #0a0a0a;
}

body {
  font-family: system-ui, -apple-system, Segoe UI, Roboto, Helvetica, Arial, sans-serif;
}

button, input {
  font: inherit;
}

.page {
  width: 100%;
  min-height: 100vh;
  padding: 24px;
  display: grid;
  place-items: center;
  color: #e5e7eb;
}

.card {
  width: 100%;
  max-width: 620px;
  min-width: 0;
  padding: 18px;
  display: grid;
  gap: 14px;
  border: 1px solid #1f2937;
  border-radius: 16px;
  background: #0b1020;
}

h1 {
  margin: 0;
  font-size: 21px;
}

.subtitle {
  margin: 0;
  color: #9ca3af;
  font-size: 13px;
  line-height: 1.5;
}

.toolbar {
  display: flex;
  flex-wrap: wrap;
  align-items: end;
  gap: 10px;
}

.limit-control {
  display: grid;
  gap: 6px;
  color: #cbd5e1;
  font-size: 12px;
}

.limit-control input {
  width: 110px;
  padding: 9px 10px;
  border: 1px solid #374151;
  border-radius: 10px;
  background: #0a0f1e;
  color: #e5e7eb;
}

.reset-button,
.remove-button,
.counter-button {
  border: 1px solid #374151;
  border-radius: 10px;
  color: #e5e7eb;
}

.reset-button,
.remove-button {
  padding: 9px 12px;
  background: #111827;
  cursor: pointer;
}

button:disabled {
  cursor: not-allowed;
  opacity: 0.48;
}

.status {
  margin: 0;
  padding: 9px 11px;
  border: 1px solid #1f2937;
  border-radius: 10px;
  background: #0a0f1e;
  color: #bfdbfe;
  font-size: 13px;
}

.counter-list {
  width: 100%;
  min-width: 0;
  display: grid;
  gap: 9px;
}

.counter-row {
  min-width: 0;
  display: grid;
  grid-template-columns: minmax(0, 1fr) auto;
  gap: 9px;
}

.counter-button {
  min-width: 0;
  padding: 11px 14px;
  overflow-wrap: anywhere;
  background: #0a0f1e;
  text-align: left;
  cursor: pointer;
}

.counter-value {
  color: #a3e635;
  font-weight: 800;
}

.counter-button:hover,
.remove-button:hover:not(:disabled),
.reset-button:hover:not(:disabled) {
  border-color: #60a5fa;
}

.counter-button:focus-visible,
.remove-button:focus-visible,
.reset-button:focus-visible,
.limit-control input:focus-visible {
  outline: 3px solid #a3e635;
  outline-offset: 2px;
}

@media (max-width: 520px) {
  .page {
    padding: 12px;
  }

  .card {
    padding: 14px;
  }

  .counter-row {
    grid-template-columns: minmax(0, 1fr);
  }
}
